INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2024-05-21-ghana-evat-phase-one-a-year-late', '2024-05-21', '2024-05', 'Six hundred named VAT-registered taxpayers were called to mandatory onboarding meetings in Accra. The published 2023 timetable had this phase finished by June 2023.', '<h3>🇬🇭 E-VAT Phase 1 finally onboards, about a year behind the plan</h3><p>The Ghana Revenue Authority called six hundred named VAT-registered taxpayers to mandatory onboarding meetings in Accra this week, bringing them onto the Certified Invoicing System.</p><p>Worth reading against the plan. The timetable the GRA published in March 2023 had Phase 1 running from March to June 2023, Phase 2 to December 2023, and every VAT-registered taxpayer onboarded by December 2024. Phase 1 is landing now, roughly a year late, which makes the December 2024 finish line look optimistic.</p><p>The system itself is a certified-invoicing model rather than a government portal: accredited software on the taxpayer''s own side stamps each invoice with a daily key issued by the GRA and forwards it to the authority. That architecture is why offline operation is possible at all, and why the compliance question is as much about connectivity as about software.</p>', 'https://gra.gov.gh/gra-invites-businesses-to-e-vat-implementation-meeting/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2024-05-21-ghana-evat-phase-one-a-year-late', id FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2024-05-21-ghana-evat-phase-one-a-year-late', 'en', '🇬🇭 E-VAT Phase 1 finally onboards, about a year behind the plan', 'Six hundred named VAT-registered taxpayers were called to mandatory onboarding meetings in Accra. The published 2023 timetable had this phase finished by June 2023.', '<h3>🇬🇭 E-VAT Phase 1 finally onboards, about a year behind the plan</h3><p>The Ghana Revenue Authority called six hundred named VAT-registered taxpayers to mandatory onboarding meetings in Accra this week, bringing them onto the Certified Invoicing System.</p><p>Worth reading against the plan. The timetable the GRA published in March 2023 had Phase 1 running from March to June 2023, Phase 2 to December 2023, and every VAT-registered taxpayer onboarded by December 2024. Phase 1 is landing now, roughly a year late, which makes the December 2024 finish line look optimistic.</p><p>The system itself is a certified-invoicing model rather than a government portal: accredited software on the taxpayer''s own side stamps each invoice with a daily key issued by the GRA and forwards it to the authority. That architecture is why offline operation is possible at all, and why the compliance question is as much about connectivity as about software.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2024-05-21-ghana-evat-phase-one-a-year-late', 'es', '🇬🇭 La Fase 1 de E-VAT se incorpora por fin, con un año de retraso', 'Seiscientos contribuyentes nombrados fueron convocados a reuniones obligatorias de incorporación en Accra. El calendario publicado en 2023 daba esta fase por concluida en junio de 2023.', '<h3>🇬🇭 La Fase 1 de E-VAT se incorpora por fin, con un año de retraso</h3><p>La Autoridad Tributaria de Ghana convocó esta semana a seiscientos contribuyentes nombrados, inscritos en el IVA, a reuniones obligatorias de incorporación en Accra, para sumarlos al Sistema Certificado de Facturación.</p><p>Conviene leerlo frente al plan. El calendario que la GRA publicó en marzo de 2023 situaba la Fase 1 entre marzo y junio de 2023, la Fase 2 hasta diciembre de 2023 y a todos los inscritos en el IVA para diciembre de 2024. La Fase 1 llega ahora, con cerca de un año de retraso, lo que hace que la meta de diciembre de 2024 parezca optimista.</p><p>El sistema es un modelo de facturación certificada y no un portal público: software acreditado del lado del propio contribuyente sella cada factura con una clave diaria emitida por la GRA y la reenvía a la administración. Esa arquitectura explica que sea posible operar sin conexión, y que la cuestión del cumplimiento tenga tanto que ver con la conectividad como con el software.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2024-05-21-ghana-evat-phase-one-a-year-late', 'de', '🇬🇭 E-VAT-Phase 1 startet endlich, rund ein Jahr hinter dem Plan', 'Sechshundert namentlich benannte MWST-registrierte Steuerpflichtige wurden zu verbindlichen Onboarding-Treffen nach Accra geladen. Der 2023 veröffentlichte Zeitplan sah diese Phase im Juni 2023 abgeschlossen.', '<h3>🇬🇭 E-VAT-Phase 1 startet endlich, rund ein Jahr hinter dem Plan</h3><p>Die ghanaische Steuerbehörde lud diese Woche sechshundert namentlich benannte, umsatzsteuerlich registrierte Steuerpflichtige zu verbindlichen Onboarding-Treffen in Accra und bringt sie damit auf das zertifizierte Rechnungssystem.</p><p>Lesenswert im Vergleich zum Plan. Der im März 2023 veröffentlichte Zeitplan sah Phase 1 von März bis Juni 2023 vor, Phase 2 bis Dezember 2023 und alle MWST-Registrierten bis Dezember 2024. Phase 1 kommt jetzt, etwa ein Jahr später, was die Ziellinie Dezember 2024 optimistisch erscheinen lässt.</p><p>Das System ist ein zertifiziertes Rechnungsmodell und kein Behördenportal: akkreditierte Software auf Seiten des Steuerpflichtigen stempelt jede Rechnung mit einem von der GRA ausgegebenen Tagesschlüssel und leitet sie an die Behörde weiter. Diese Architektur macht Offline-Betrieb überhaupt erst möglich und die Compliance-Frage ebenso sehr zu einer Frage der Konnektivität wie der Software.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2024-05-21-ghana-evat-phase-one-a-year-late', 'fr', '🇬🇭 La phase 1 d''E-VAT démarre enfin, avec près d''un an de retard', 'Six cents assujettis nommément désignés ont été convoqués à des réunions obligatoires d''intégration à Accra. Le calendrier publié en 2023 donnait cette phase achevée en juin 2023.', '<h3>🇬🇭 La phase 1 d''E-VAT démarre enfin, avec près d''un an de retard</h3><p>L''administration fiscale ghanéenne a convoqué cette semaine six cents assujettis à la TVA nommément désignés à des réunions obligatoires d''intégration à Accra, afin de les faire entrer dans le système certifié de facturation.</p><p>À lire face au plan. Le calendrier publié par la GRA en mars 2023 prévoyait la phase 1 de mars à juin 2023, la phase 2 jusqu''en décembre 2023 et l''ensemble des assujettis pour décembre 2024. La phase 1 arrive maintenant, avec environ un an de retard, ce qui rend l''échéance de décembre 2024 optimiste.</p><p>Le système relève d''un modèle de facturation certifiée et non d''un portail public : un logiciel accrédité, côté contribuable, estampille chaque facture avec une clé du jour délivrée par la GRA et la transmet à l''administration. Cette architecture explique que le fonctionnement hors ligne soit possible, et que la question de la conformité tienne autant à la connectivité qu''au logiciel.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2026-01-01-ghana-act-1151-stops-asking-who-you-are', '2026-01-01', '2026-01', 'The Value Added Tax Act, 2025 replaced a phased onboarding programme with a general duty on every taxable person. The same day changed the rate, both registration thresholds, the flat-rate scheme and the penalty ceiling.', '<h3>🇬🇭 Act 1151 stops asking who you are — certified invoicing becomes universal</h3><p>Ghana''s Value Added Tax Act, 2025 (Act 1151) takes effect today, replacing Act 870. Section 43(2) requires every taxable person to issue tax invoices through a Certified Invoicing System integrated with the Commissioner-General''s. Until today the question was whether the GRA had written to you; from today it is simply whether you are a taxable person.</p><p>Four other things changed on the same date, and one of them is easy to miss. The COVID-19 Health Recovery Levy is abolished, and NHIL and GETFund now sit on a common base and are deductible as input tax, taking the headline rate from about 21.9% to <strong>20%</strong>. The VAT Flat Rate Scheme is abolished. The penalty ceiling for invoicing outside the certified system rises from 500 currency points to 50,000 — a hundredfold.</p><p><strong>And the registration threshold became two thresholds.</strong> For goods it rose from GHS 200,000 to GHS 750,000. For services it was removed entirely: registration now follows from commencing taxable activity, within thirty days, whatever the turnover. The GRA''s own notice announces the first and is silent on the second, which means every consultant, freelancer and digital service provider in Ghana has to read past the headline to find out that the threshold protecting them no longer exists.</p>', 'https://gra.gov.gh/news/portfolio/notice-to-all-vat-registered-taxpayers/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-01-01-ghana-act-1151-stops-asking-who-you-are', id FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-01-01-ghana-act-1151-stops-asking-who-you-are', 'en', '🇬🇭 Act 1151 stops asking who you are — certified invoicing becomes universal', 'The Value Added Tax Act, 2025 replaced a phased onboarding programme with a general duty on every taxable person. The same day changed the rate, both registration thresholds, the flat-rate scheme and the penalty ceiling.', '<h3>🇬🇭 Act 1151 stops asking who you are — certified invoicing becomes universal</h3><p>Ghana''s Value Added Tax Act, 2025 (Act 1151) takes effect today, replacing Act 870. Section 43(2) requires every taxable person to issue tax invoices through a Certified Invoicing System integrated with the Commissioner-General''s. Until today the question was whether the GRA had written to you; from today it is simply whether you are a taxable person.</p><p>Four other things changed on the same date, and one of them is easy to miss. The COVID-19 Health Recovery Levy is abolished, and NHIL and GETFund now sit on a common base and are deductible as input tax, taking the headline rate from about 21.9% to <strong>20%</strong>. The VAT Flat Rate Scheme is abolished. The penalty ceiling for invoicing outside the certified system rises from 500 currency points to 50,000 — a hundredfold.</p><p><strong>And the registration threshold became two thresholds.</strong> For goods it rose from GHS 200,000 to GHS 750,000. For services it was removed entirely: registration now follows from commencing taxable activity, within thirty days, whatever the turnover. The GRA''s own notice announces the first and is silent on the second, which means every consultant, freelancer and digital service provider in Ghana has to read past the headline to find out that the threshold protecting them no longer exists.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-01-01-ghana-act-1151-stops-asking-who-you-are', 'es', '🇬🇭 La Ley 1151 deja de preguntar quién es usted: la facturación certificada se generaliza', 'La Ley del IVA de 2025 sustituyó un programa de incorporación por fases por un deber general de todo sujeto pasivo. El mismo día cambiaron el tipo, ambos umbrales de registro, el régimen de tipo fijo y el techo sancionador.', '<h3>🇬🇭 La Ley 1151 deja de preguntar quién es usted: la facturación certificada se generaliza</h3><p>La Ley del Impuesto sobre el Valor Añadido de 2025 (Ley 1151) entra hoy en vigor en Ghana y sustituye a la Ley 870. Su artículo 43(2) exige que todo sujeto pasivo emita facturas mediante un Sistema Certificado de Facturación integrado con el del Comisionado General. Hasta hoy la pregunta era si la GRA le había escrito; desde hoy es sencillamente si usted es sujeto pasivo.</p><p>Otras cuatro cosas cambiaron en la misma fecha, y una es fácil de pasar por alto. Se abolió la Tasa COVID-19 de Recuperación Sanitaria, y NHIL y GETFund pasan a calcularse sobre base común y a ser deducibles como impuesto soportado, lo que lleva el tipo global de cerca del 21,9 % al <strong>20 %</strong>. Se suprime el Régimen de Tipo Fijo del IVA. El techo sancionador por facturar fuera del sistema certificado sube de 500 a 50.000 puntos de moneda: cien veces más.</p><p><strong>Y el umbral de registro se convirtió en dos umbrales.</strong> Para bienes subió de 200.000 a 750.000 GHS. Para servicios se eliminó por completo: el registro deriva ahora del inicio de la actividad gravada, en treinta días, sea cual sea la cifra de negocio. El aviso de la propia GRA anuncia lo primero y calla lo segundo, de modo que cada consultor, autónomo y proveedor digital de Ghana tiene que leer más allá del titular para descubrir que el umbral que le protegía ya no existe.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-01-01-ghana-act-1151-stops-asking-who-you-are', 'de', '🇬🇭 Gesetz 1151 fragt nicht mehr, wer Sie sind — zertifizierte Rechnungsstellung wird allgemein', 'Das Mehrwertsteuergesetz 2025 ersetzte ein phasenweises Onboarding-Programm durch eine allgemeine Pflicht jedes Steuerpflichtigen. Am selben Tag änderten sich Satz, beide Registrierungsschwellen, das Pauschalsystem und die Sanktionsobergrenze.', '<h3>🇬🇭 Gesetz 1151 fragt nicht mehr, wer Sie sind — zertifizierte Rechnungsstellung wird allgemein</h3><p>Ghanas Mehrwertsteuergesetz 2025 (Gesetz 1151) tritt heute in Kraft und ersetzt Gesetz 870. Art. 43(2) verlangt von jedem Steuerpflichtigen, Rechnungen über ein zertifiziertes Rechnungssystem auszustellen, das mit dem des Commissioner-General verbunden ist. Bis heute lautete die Frage, ob die GRA Ihnen geschrieben hatte; ab heute lautet sie schlicht, ob Sie steuerpflichtig sind.</p><p>Vier weitere Dinge änderten sich am selben Datum, eines davon leicht zu übersehen. Die COVID-19-Abgabe entfällt, NHIL und GETFund stehen nun auf gemeinsamer Basis und sind als Vorsteuer abziehbar, was den Gesamtsatz von rund 21,9 % auf <strong>20 %</strong> senkt. Das MWST-Pauschalsystem wird abgeschafft. Die Sanktionsobergrenze für Rechnungen ausserhalb des zertifizierten Systems steigt von 500 auf 50.000 Währungspunkte — hundertfach.</p><p><strong>Und aus der Registrierungsschwelle wurden zwei.</strong> Für Waren stieg sie von 200.000 auf 750.000 GHS. Für Dienstleistungen entfiel sie ganz: die Registrierung folgt nun aus der Aufnahme der steuerbaren Tätigkeit, binnen dreissig Tagen, unabhängig vom Umsatz. Die Mitteilung der GRA nennt das Erste und schweigt zum Zweiten, sodass jeder Berater, Freiberufler und digitale Anbieter in Ghana über die Schlagzeile hinauslesen muss, um zu erfahren, dass die ihn schützende Schwelle nicht mehr existiert.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-01-01-ghana-act-1151-stops-asking-who-you-are', 'fr', '🇬🇭 La loi 1151 cesse de demander qui vous êtes — la facturation certifiée devient générale', 'La loi TVA de 2025 a remplacé un programme d''intégration par phases par une obligation générale de tout assujetti. Le même jour ont changé le taux, les deux seuils d''assujettissement, le régime forfaitaire et le plafond de sanction.', '<h3>🇬🇭 La loi 1151 cesse de demander qui vous êtes — la facturation certifiée devient générale</h3><p>La loi ghanéenne sur la taxe sur la valeur ajoutée de 2025 (loi 1151) entre en vigueur aujourd''hui et remplace la loi 870. Son article 43(2) impose à tout assujetti d''émettre ses factures au moyen d''un système certifié relié à celui du Commissioner-General. Jusqu''à aujourd''hui, la question était de savoir si la GRA vous avait écrit ; à partir d''aujourd''hui, elle est simplement de savoir si vous êtes assujetti.</p><p>Quatre autres choses ont changé à la même date, dont une facile à manquer. La taxe COVID-19 est supprimée, NHIL et GETFund reposent désormais sur une base commune et sont déductibles en amont, ce qui ramène le taux global d''environ 21,9 % à <strong>20 %</strong>. Le régime de taux forfaitaire est aboli. Le plafond de sanction pour facturation hors système certifié passe de 500 à 50 000 points monétaires — centuplé.</p><p><strong>Et le seuil d''assujettissement est devenu deux seuils.</strong> Pour les biens, il est passé de 200 000 à 750 000 GHS. Pour les services, il a été supprimé : l''assujettissement découle désormais du début de l''activité taxable, dans les trente jours, quel que soit le chiffre d''affaires. L''avis de la GRA annonce le premier et tait le second, de sorte que chaque consultant, indépendant et prestataire numérique du Ghana doit lire au-delà du titre pour découvrir que le seuil qui le protégeait n''existe plus.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2026-07-28-ghana-parliament-buys-forty-thousand-fiscal-devices', '2026-07-28', '2026-07', 'A multi-year expenditure commitment was approved for the Fiscal Electronic Device policy, targeting forty thousand devices at retail points of sale. The invoicing duty was already general; this is about the tills.', '<h3>🇬🇭 Parliament buys forty thousand fiscal devices, and the retail layer arrives</h3><p>Parliament has approved a multi-year expenditure commitment for the Fiscal Electronic Device policy under the Taxation (Use of Fiscal Electronic Device) Act, 2018, targeting forty thousand devices at retail points of sale. Reporting put the end of the pilot in August 2026, with deployment following, and a first phase aimed at mid-sized shops.</p><p>It is worth being clear about what this does and does not change. The duty to invoice through a certified system has been general since January, so this is not a new obligation on business at large — Act 1151 s.43(9) already treats a fiscal receipt as satisfying the invoicing requirement. What the devices change is the retail end, where the gap between what is sold and what is recorded has always been widest. The Commissioner-General said in February that VAT captures roughly 40% of its potential.</p><p>The enforcement context is not theoretical. GRA field operations across Accra in May 2026 found businesses issuing receipts selectively and keeping incomplete records; premises were sealed and an arrest was made. Minority MPs objected to the approval on the grounds that neither the number of commitments nor the total cost was specified.</p>', 'https://www.citinewsroom.com/2026/07/parliament-approves-gra-deal-to-roll-out-fiscal-electronic-device-policy/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-07-28-ghana-parliament-buys-forty-thousand-fiscal-devices', id FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-07-28-ghana-parliament-buys-forty-thousand-fiscal-devices', 'en', '🇬🇭 Parliament buys forty thousand fiscal devices, and the retail layer arrives', 'A multi-year expenditure commitment was approved for the Fiscal Electronic Device policy, targeting forty thousand devices at retail points of sale. The invoicing duty was already general; this is about the tills.', '<h3>🇬🇭 Parliament buys forty thousand fiscal devices, and the retail layer arrives</h3><p>Parliament has approved a multi-year expenditure commitment for the Fiscal Electronic Device policy under the Taxation (Use of Fiscal Electronic Device) Act, 2018, targeting forty thousand devices at retail points of sale. Reporting put the end of the pilot in August 2026, with deployment following, and a first phase aimed at mid-sized shops.</p><p>It is worth being clear about what this does and does not change. The duty to invoice through a certified system has been general since January, so this is not a new obligation on business at large — Act 1151 s.43(9) already treats a fiscal receipt as satisfying the invoicing requirement. What the devices change is the retail end, where the gap between what is sold and what is recorded has always been widest. The Commissioner-General said in February that VAT captures roughly 40% of its potential.</p><p>The enforcement context is not theoretical. GRA field operations across Accra in May 2026 found businesses issuing receipts selectively and keeping incomplete records; premises were sealed and an arrest was made. Minority MPs objected to the approval on the grounds that neither the number of commitments nor the total cost was specified.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-07-28-ghana-parliament-buys-forty-thousand-fiscal-devices', 'es', '🇬🇭 El Parlamento compra cuarenta mil dispositivos fiscales y llega la capa minorista', 'Se aprobó un compromiso de gasto plurianual para la política de Dispositivos Fiscales Electrónicos, con el objetivo de cuarenta mil aparatos en puntos de venta. El deber de facturar ya era general; esto va de las cajas.', '<h3>🇬🇭 El Parlamento compra cuarenta mil dispositivos fiscales y llega la capa minorista</h3><p>El Parlamento ha aprobado un compromiso de gasto plurianual para la política de Dispositivos Fiscales Electrónicos prevista en la Ley de Uso de Dispositivos Fiscales Electrónicos de 2018, con el objetivo de cuarenta mil aparatos en puntos de venta minoristas. Las informaciones situaban el fin del piloto en agosto de 2026, con el despliegue a continuación y una primera fase dirigida a comercios medianos.</p><p>Conviene precisar qué cambia y qué no. El deber de facturar mediante un sistema certificado es general desde enero, así que no es una obligación nueva para las empresas en general: el art. 43(9) de la Ley 1151 ya considera que un tique fiscal satisface el requisito de facturación. Lo que los dispositivos cambian es el extremo minorista, donde la brecha entre lo vendido y lo registrado siempre ha sido mayor. El Comisionado General dijo en febrero que el IVA capta en torno al 40 % de su potencial.</p><p>El contexto de fiscalización no es teórico. Operaciones de campo de la GRA por Accra en mayo de 2026 hallaron empresas que emitían tiques selectivamente y llevaban registros incompletos; se precintaron locales y se practicó una detención. Diputados de la minoría objetaron a la aprobación porque no se especificaron ni el número de compromisos ni el coste total.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-07-28-ghana-parliament-buys-forty-thousand-fiscal-devices', 'de', '🇬🇭 Das Parlament kauft vierzigtausend Fiskalgeräte, und die Einzelhandelsebene kommt', 'Eine mehrjährige Ausgabenverpflichtung für die Politik der fiskalischen elektronischen Geräte wurde bewilligt, mit dem Ziel von vierzigtausend Geräten an Verkaufsstellen. Die Rechnungspflicht war bereits allgemein; hier geht es um die Kassen.', '<h3>🇬🇭 Das Parlament kauft vierzigtausend Fiskalgeräte, und die Einzelhandelsebene kommt</h3><p>Das Parlament hat eine mehrjährige Ausgabenverpflichtung für die Politik der fiskalischen elektronischen Geräte nach dem Gesetz von 2018 bewilligt, mit dem Ziel von vierzigtausend Geräten an Einzelhandelskassen. Berichten zufolge endete der Pilot im August 2026, danach folgt die Ausbringung, deren erste Phase auf mittelgrosse Geschäfte zielt.</p><p>Es lohnt, klar zu benennen, was sich damit ändert und was nicht. Die Pflicht, über ein zertifiziertes System zu fakturieren, gilt seit Januar allgemein; dies ist also keine neue Pflicht für die Wirtschaft insgesamt — Art. 43(9) des Gesetzes 1151 lässt einen Fiskalbeleg bereits als Erfüllung der Rechnungspflicht gelten. Was die Geräte ändern, ist das Einzelhandelsende, wo die Lücke zwischen Verkauftem und Erfasstem stets am grössten war. Der Commissioner-General sagte im Februar, die Mehrwertsteuer erfasse rund 40 % ihres Potenzials.</p><p>Der Durchsetzungskontext ist nicht theoretisch. Feldeinsätze der GRA in Accra fanden im Mai 2026 Betriebe, die Belege selektiv ausgaben und unvollständige Aufzeichnungen führten; Geschäftsräume wurden versiegelt und eine Festnahme erfolgte. Abgeordnete der Minderheit widersprachen der Bewilligung, weil weder die Zahl der Verpflichtungen noch die Gesamtkosten benannt wurden.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-07-28-ghana-parliament-buys-forty-thousand-fiscal-devices', 'fr', '🇬🇭 Le Parlement achète quarante mille appareils fiscaux, et la couche commerce de détail arrive', 'Un engagement de dépense pluriannuel a été approuvé pour la politique des appareils fiscaux électroniques, visant quarante mille appareils aux points de vente. L''obligation de facturer était déjà générale ; ici, il s''agit des caisses.', '<h3>🇬🇭 Le Parlement achète quarante mille appareils fiscaux, et la couche commerce de détail arrive</h3><p>Le Parlement a approuvé un engagement de dépense pluriannuel pour la politique des appareils fiscaux électroniques prévue par la loi de 2018, visant quarante mille appareils aux points de vente de détail. La presse situait la fin du pilote en août 2026, le déploiement suivant, avec une première phase visant les commerces de taille moyenne.</p><p>Il vaut la peine de préciser ce que cela change et ne change pas. L''obligation de facturer par un système certifié est générale depuis janvier : ce n''est donc pas une obligation nouvelle pour les entreprises en général — l''article 43(9) de la loi 1151 admet déjà qu''un ticket fiscal satisfait l''exigence de facturation. Ce que les appareils changent, c''est l''extrémité commerce de détail, où l''écart entre ce qui est vendu et ce qui est enregistré a toujours été le plus large. Le Commissioner-General déclarait en février que la TVA ne capte qu''environ 40 % de son potentiel.</p><p>Le contexte de contrôle n''est pas théorique. Des opérations de terrain de la GRA dans Accra ont relevé en mai 2026 des entreprises émettant des tickets de façon sélective et tenant des registres incomplets ; des locaux ont été scellés et une arrestation a eu lieu. Des députés de la minorité ont contesté l''approbation, au motif que ni le nombre d''engagements ni le coût total n''étaient précisés.</p>');

